    var g = klon.querySelector("#gambar-sampul"); if (g) g.removeAttribute("src");
    var vm = klon.querySelector("#video-mars");
    if (vm) { vm.removeAttribute("src"); vm.removeAttribute("poster"); }
    var tm = klon.querySelector("#tirai-mars");
    if (tm) { tm.classList.remove("buka"); tm.setAttribute("aria-hidden", "true"); }
    var l = klon.querySelector("#logo-rak"); if (l) l.removeAttribute("src");
    var b = klon.querySelector("body"); if (b) b.className = "";
    var r = klon.querySelector("#rak"); if (r) r.classList.remove("buka");
    var lama = klon.querySelector("#sunting-bawaan"); if (lama) lama.parentNode.removeChild(lama);
    var sk = document.createElement("script");
    sk.id = "sunting-bawaan";
    sk.textContent = "window.__SUNTINGAN_AWAL = " + JSON.stringify(SUNTINGAN) + ";";
    klon.querySelector("head").appendChild(sk);
    var berkas = new Blob(["<!DOCTYPE html>\n" + klon.outerHTML], { type: "text/html;charset=utf-8" });
    var a = document.createElement("a");
